#!/bin/bash
set -euo pipefail
echo "==== Conversation-only recording (start on agent answer) ===="
B_IN=''
B_RE=''
echo "$B_IN" | base64 -d > /tmp/skykin_inbound.lua
echo "$B_RE" | base64 -d > /tmp/skykin_record_on_agent.lua

# Install into FreeSWITCH container
docker cp /tmp/skykin_inbound.lua skykin-freeswitch:/etc/freeswitch/scripts/skykin_inbound.lua
docker cp /tmp/skykin_record_on_agent.lua skykin-freeswitch:/etc/freeswitch/scripts/skykin_record_on_agent.lua

# Persist for container recreate
mkdir -p /opt/skykin/fs-live
cp -f /tmp/skykin_inbound.lua /opt/skykin/fs-live/skykin_inbound.lua
cp -f /tmp/skykin_record_on_agent.lua /opt/skykin/fs-live/skykin_record_on_agent.lua

# Stop recording on IVR answer in live DID dialplans
python3 - <<'PY'
from pathlib import Path
import subprocess
cands = [
  "/opt/skykin/fs-live/02_skykin_did_ahununu.xml",
  "/opt/skykin/fs-live/01_skykin_did.xml",
]
# Also pull from container if live copies missing
for remote in (
  "/etc/freeswitch/dialplan/public/02_skykin_did_ahununu.xml",
  "/etc/freeswitch/dialplan/public/01_skykin_did.xml",
):
  local = "/tmp/" + Path(remote).name
  subprocess.run(["docker","cp", f"skykin-freeswitch:{remote}", local], check=False)
  if Path(local).exists():
    cands.append(local)

seen=set()
for p in cands:
  path=Path(p)
  if not path.exists() or str(path) in seen:
    continue
  seen.add(str(path))
  t=path.read_text(encoding="utf-8", errors="replace")
  old=t
  t=t.replace(
    'execute_on_answer=record_session ${record_path}/${record_name}',
    'execute_on_answer='
  )
  t=t.replace(
    'execute_on_answer=record_session \${record_path}/\${record_name}',
    'execute_on_answer='
  )
  # common XML forms
  import re
  t=re.sub(
    r'<action application="set" data="execute_on_answer=record_session[^"]*"/>',
    '<action application="set" data="execute_on_answer="/>',
    t
  )
  if t!=old:
    path.write_text(t, encoding="utf-8")
    print("patched", path)
    # push back into container public dialplan when tmp
    name=path.name
    if name.startswith("0"):
      subprocess.run(["docker","cp", str(path), f"skykin-freeswitch:/etc/freeswitch/dialplan/public/{name}"], check=False)
      live=Path("/opt/skykin/fs-live")/name
      live.write_text(t, encoding="utf-8")
      print("saved", live)
  else:
    print("no record-on-answer change", path)
PY

# Callcenter: record only after agent answers
python3 - <<'PY'
from pathlib import Path
import subprocess
for src,dst in [
  ("skykin-freeswitch:/etc/freeswitch/autoload_configs/callcenter.conf.xml", "/tmp/callcenter.conf.xml"),
]:
  subprocess.run(["docker","cp", src, dst], check=False)
p=Path("/tmp/callcenter.conf.xml")
if p.exists():
  t=p.read_text(encoding="utf-8", errors="replace")
  if "record-template" not in t:
    t=t.replace(
      '<param name="moh-sound" value=""/>',
      '<param name="moh-sound" value=""/>\n      <param name="record-template" value="${record_path}/${record_name}"/>',
      1
    )
    # only first queue may have been updated; do all moh-sound lines
    if t.count("record-template") < 1:
      t=t.replace(
        '<param name="moh-sound" value=""/>',
        '<param name="moh-sound" value=""/>\n      <param name="record-template" value="${record_path}/${record_name}"/>'
      )
    p.write_text(t, encoding="utf-8")
    subprocess.run(["docker","cp", str(p), "skykin-freeswitch:/etc/freeswitch/autoload_configs/callcenter.conf.xml"], check=True)
    Path("/opt/skykin/fs-live/callcenter.conf.xml").write_text(t, encoding="utf-8")
    print("callcenter record-template added")
  else:
    print("callcenter already has record-template")
PY

docker exec skykin-freeswitch fs_cli -x "reloadxml" || true
docker exec skykin-freeswitch fs_cli -x "reload mod_callcenter" || true
echo "VERIFY lua:"
docker exec skykin-freeswitch sh -c "grep -n 'api_on_answer\|execute_on_answer' /etc/freeswitch/scripts/skykin_inbound.lua | head -20"
docker exec skykin-freeswitch sh -c "ls -la /etc/freeswitch/scripts/skykin_record_on_agent.lua"
echo "DONE — new inbound calls record conversation only (after agent answer)."
echo "Existing WAVs still contain IVR; only new calls are fixed."
